function makeLangMap(
  en: string,
  hi?: string,
  te?: string,
  kn?: string,
  ta?: string,
  mr?: string,
  or?: string,
  bn?: string
): Record<LanguageCode, string> {
  return {
    en,
    hi: hi || en,
    te: te || en,
    kn: kn || en,
    ta: ta || en,
    mr: mr || hi || en,
    or: or || en,
    bn: bn || en,
  };
}

