      'அரச வம்சாவளிகளிலும் போர் சமூக மரபுகளிலும் போற்றப்படும் மன்னர் ரகுவுடன் தொடர்புடைய சூரிய வம்சத்தின் (சூர்யவம்சம்) கிளை.',
