      'गजपति और कलिंग-आंध्र शिलालेखों में प्रमाणित संस्कृत शाही और सामरिक उपाधि जो सूर्यवंशी क्षत्रिय संप्रभुता को दर्शाती है।',
      'గజపతి మరియు కళింగాంధ్ర శాసనాలలో ధృవీకరించబడిన సూర్యవంశ క్షత్రియ సార్వభౌమత్వాన్ని సూచించే సంస్కృత రాజ మరియు సైనిక బిరుదు.',
      'ಗಜಪತಿ ಮತ್ತು ಕಳಿಂಗ-ಆಂಧ್ರ ಶಾಸನಗಳಲ್ಲಿ ದೃಢೀಕರಿಸಲ್ಪಟ್ಟ ಸೂರ್ಯವಂಶದ ಕ್ಷತ್ರಿಯ ಸಾರ್ವಭೌಮತ್ವವನ್ನು ಸೂಚಿಸುವ ಸಂಸ್ಕೃತ ರಾಜ ಮತ್ತು ಸಮರ ಬಿರುದು.',
