      'गजपती आणि कलिंग-आंध्र शिलालेखांमध्ये प्रमाणित असलेली सूर्यवंशी क्षत्रिय सार्वभौमत्व दर्शवणारी संस्कृत राजकीय व लष्करी पदवी.',
