      'ತೆಲುಗು ಮೌಖಿಕ ಇತಿಹಾಸ, ಕೈಫಿಯತ್ತುಗಳು ಮತ್ತು ಪಾಳೆಯಗಾರ ಸಂಪ್ರದಾಯಗಳಲ್ಲಿ ವ್ಯಾಪಕವಾಗಿ ಕಂಡುಬರುವ ಒಡ್ಡೆರಾಜುಲು / ವಡ್ಡರ ರಾಜುಲು ಎಂಬುದರ ಸಂಯುಕ್ತ ರಾಜವಂಶದ ರೂಪ.',
      'தெலுங்கு வாய்மொழி வரலாறுகள், கைஃபியத்துகள் மற்றும் பாளையக்காரர் மரபுகளில் சான்றளிக்கப்பட்ட ஒட்டெராஜுலு / வடெர ராஜுலு என்பதன் கூட்டு அரச வம்ச வடிவம்.',
      'तेलुगू मौखिक इतिहास, कैफियत आणि पालेगार परंपरांमध्ये आढळणारे ओड्डेराजुलु / वड्डेरा राजुलु या राजवंशीय नावाचे संयुक्त रूप.',
