      'ತೆಲುಗು ಮತ್ತು ಕನ್ನಡ ಗಡಿಭಾಗದ ವಂಶಗಳಲ್ಲಿ ಉಳಿಸಿಕೊಂಡಿರುವ ಒಡಿಯರಾಜುಲು ಎಂಬ ಪದದ ಪ್ರಾದೇಶಿಕ ಉಚ್ಚಾರಣಾ ರೂಪಾಂತರ (ವಡಿಯರಾಜುಲು).',
      'தெலுங்கு மற்றும் கன்னட எல்லைப்புற வம்சங்களில் பாதுகாக்கப்பட்டுள்ள ஒடியராஜுலு என்பதன் பிராந்திய ஒலிப்பு வடிவம் (வடியராஜுலு).',
      'तेलुगू आणि कन्नड सीमावर्ती घराण्यांमध्ये जपलेले ओडियाराजुलु या नावाचे प्रादेशिक ध्वन्यात्मक रूप (वडियाराजुलु).',
      'ତେଲୁଗୁ ଏବଂ କର୍ଣ୍ଣାଟକ ସୀମାନ୍ତ ବଂଶଗୁଡ଼ିକରେ ସଂରକ୍ଷିତ ଓଡ଼ିଆରାଜୁଲୁ ଶବ୍ଦର ଆଞ୍ଚଳିକ ଧ୍ୱନିଗତ ରୂପାନ୍ତର (ବଡ଼ିଆରାଜୁଲୁ)।',
      'তেলুগু ও কন্নড় সীমান্তবর্তী বংশগুলিতে সংরক্ষিত ওড়িয়ারাজুলু নামের আঞ্চলিক ধ্বনিগত রূপান্তর (বড়িয়ারাজুলু)।'
