      'அசோகரின் கல்வெட்டுகள், காரவேலரின் ஹதிகும்பா கல்வெட்டு மற்றும் கலிங்க-கஜபதி சாசனங்களில் போற்றப்படும் கடலோர ஒடிசா மற்றும் வட ஆந்திராவை உள்ளடக்கிய வரலாற்றுப் பேரரசு நிலப்பரப்பு (கலிங்கம்).',
