      'ರಾಜಸ್ಥಾನ, ಹರಿಯಾಣ, ಪಂಜಾಬ್, ಸಿಂಧ್, ಗುಜರಾತ್ ಮತ್ತು ದೆಹಲಿಯ ಅಧಿಕೃತ ದಾಖಲೆಗಳಲ್ಲಿ ಓಡ್ (Od) ಪದಕ್ಕೆ ವ್ಯಾಪಕವಾಗಿ ಬಳಸಲಾಗುವ ಪ್ರಮಾಣಿತ ರೋಮನ್ ಕಾಗುಣಿತ (Oad).',
      'ராஜஸ்தான், ஹரியானா, பஞ்சாப், சிந்து, குஜராத் மற்றும் டெல்லி அரசு ஆவணங்களில் ஓட் (Od) என்பதற்குப் பரவலாகப் பயன்படுத்தப்படும் நிலையான ஆங்கில எழுத்து வடிவம் (Oad).',
