      'ஆந்திரப் பிரதேசம் மற்றும் தெலுங்கானாவில் முதன்மையான சமூகப் பெயர்; வரலாற்று ரீதியாக கோட்டை கட்டுபவர்கள், ஏரி/நீர்த்தேக்கப் பொறியாளர்கள், கற்சிற்பிகள் மற்றும் போர் வீரர்களாக ஆவணப்படுத்தப்பட்டுள்ளனர்.',
