      'అనుబంధ రిఫరెన్స్ #15: దక్షిణ భారత శాసనాలలో మరియు చారిత్రక రికార్డులలో ఓడ్ర/ఒడియ రాజవంశాలను సూచించే బహువచన నామం (ఒడియరాజులు / Odiyarajulu).',
