      'ಪೂರಕ ಉಲ್ಲೇಖ #19: ಗ್ರಾನೈಟ್ ಗಣಿಗಾರಿಕೆ, ಕಲ್ಲು ಕೆತ್ತನೆ, ದೇವಾಲಯ ವಾಸ್ತುಶಿಲ್ಪ ಮತ್ತು ಕೋಟೆ ನಿರ್ಮಾಣದಲ್ಲಿ ಪರಿಣತಿ ಹೊಂದಿರುವ ಸಾಂಪ್ರದಾಯಿಕ ವೃತ್ತಿಪರ ಉಪವಿಭಾಗ (ಕನ್ನಡ/ತೆಲುಗು "ಕಲ್ಲು" / ತಮಿಳು "ಕಲ್" / ಮರಾಠಿ "ದಗಡ್" = ಕಲ್ಲು; ಕಲ್ಲು ಒಡ್ಡರ್ / ಕಲ್ಲು ವಡ್ಡರು).',
