      'ಪೂರಕ ಉಲ್ಲೇಖ #22: ದక్కನ್, ಕರ್ನಾಟಕ ಮತ್ತು ಮಹಾರಾಷ್ಟ್ರದಾದ್ಯಂತ ಬೀಸುವ ಕಲ್ಲುಗಳು, ಗಾಣಗಳು (ಗಿರಿಣಿ/ಘಾಣಿ) ಮತ್ತು ನಿಖರವಾದ ಗೃಹ/ಕೈಗಾರಿಕಾ ಕಲ್ಲಿನ ಉಪಕರಣಗಳ ಕೆತ್ತನೆಯೊಂದಿಗೆ ಗುರುತಿಸಿಕೊಂಡಿರುವ ಸಾಂಪ್ರದಾಯಿಕ ಉಪವಿಭಾಗ (ಗಿರಿಣಿ ಒಡ್ಡರ್).',
      'துணைக் குறிப்பு #22: தக்காணம், கர்நாடகா மற்றும் மகாராஷ்டிரா முழுவதும் மாவரைக்கும் எந்திரக் கற்கள், செக்குகள் (கிரினி) மற்றும் துல்லியமான வீட்டு/தொழில்용 கல் கருவிகளைச் செதுக்குவதுடன் தொடர்புடைய பாரம்பரியப் பிரிவு (கிரினி ஒட்டர்).',
