      'पूरक संदर्भ #23 (29 में से): मद्रास प्रेसीडेंसी और मैसूर नृवंशविज्ञान सर्वेक्षणों में नमक-मिट्टी निष्कर्षण, नमक-क्यारी निर्माण और अंतर्देशीय नमक व्यापार/परिवहन के संबंध में प्रलेखित पारंपरिक उपविभाग ("उप्पु" = नमक)।',
      'అనుబంధ రిఫరెన్స్ #23: మద్రాస్ ప్రెసిడెన్సీ మరియు మైసూర్ ఎథ్నోగ్రాఫిక్ సర్వేలలో ఉప్పు మడుల నిర్మాణం మరియు ఉప్పు రవాణా/వాణిజ్యంతో ముడిపడిన సాంప్రదాయ ఉపవిభాగం (ఉప్పు ఒడ్డర్ / Uppu Oddar).',
      'ಪೂರಕ ಉಲ್ಲೇಖ #23: ಮದ್ರಾಸ್ ಪ್ರೆಸಿಡೆನ್ಸಿ ಮತ್ತು ಮೈಸೂರು ಜನಾಂಗೀಯ ಸಮೀಕ್ಷೆಗಳಲ್ಲಿ ಉಪ್ಪಿನ ಮಣ್ಣು ಸಂಸ್ಕರಣೆ, ಉಪ್ಪಿನ ಮಡಿಗಳ ನಿರ್ಮಾಣ ಮತ್ತು ಒಳನಾಡಿನ ಉಪ್ಪಿನ ವ್ಯಾಪಾರ/ಸಾಗಾಣಿಕೆಯೊಂದಿಗೆ ದಾಖಲಾಗಿರುವ ಸಾಂಪ್ರದಾಯಿಕ ಉಪವಿಭಾಗ ("ಉಪ್ಪು" = Salt; ಉಪ್ಪು ಒಡ್ಡರ್).',
      'துணைக் குறிப்பு #23: மதராஸ் மாகாணம் மற்றும் மைசூர் இனவரைவியல் ஆய்வுகளில் உப்பு மண் பிரித்தெடுத்தல், உப்பள மண் வேலைகள் மற்றும் உள்நாட்டு உப்பு வணிகம்/போக்குவரத்து தொடர்பாக ஆவணப்படுத்தப்பட்ட பாரம்பரியப் பிரிவு (உப்பு ஒட்டர் / Uppu Oddar).',
      'पूरक संदर्भ #२३: मद्रास प्रेसिडेन्सी आणि म्हैसूर मानववंशशास्त्रीय सर्वेक्षणांमध्ये मिठागरांची मातीकामे, मीठ निर्मिती व अंतर्गत मीठ व्यापार/वाहतुकीशी संबंधित म्हणून नोंदवलेला पारंपरिक उपविभाग (उप्पु ओड्डर / मीठ वडार).',
      'ଅତିରିକ୍ତ ସନ୍ଦର୍ଭ #୨୩: ମାଡ୍ରାସ ପ୍ରେସିଡେନ୍ସି ଏବଂ ମୈସୁର ନୃବଂଶ ସର୍ବେକ୍ଷଣରେ ଲୁଣ-ମାଟି ନିଷ୍କାସନ, ଲୁଣ କିଆରି ନିର୍ମାଣ ଓ ଆନ୍ତଃରାଜ୍ୟ ଲୁଣ ବାଣିଜ୍ୟ/ପରିବହନ ସହିତ ପ୍ରଲେଖିତ ପାରମ୍ପରିକ ଉପବିଭାଗ (ଉପ୍ପୁ ଓଡ଼ର)।',
      'পরিপূরক সূত্র #২৩: মাদ্রাজ প্রেসিডেন্সি ও মহীশূর নৃতাত্ত্বিক জরিপে লবণ-মাটি নিষ্কাশন, লবণক্ষেত্রের মাটির কাজ এবং অভ্যন্তরীণ লবণ বাণিজ্য/পরিবহনের সাথে যুক্ত হিসেবে নথিভুক্ত ঐতিহ্যবাহী উপবিভাগ (উপ্পু ওড্ডর)।'
